declare(strict_types=1);require_once __DIR__.'/../config/app.php';require_once __DIR__.'/../config/auth.php';require_auth();if($_SERVER['REQUEST_METHOD']!=='POST')json_error('Method not allowed',405);try{$d=read_json_body();$sid=input_str($d,'session_id');$history=$d['history']??[];$customer=$d['customer']??[];if($sid===''||!is_array($history))json_error('session_id and history are required',422);$payload=json_encode(['session_id'=>$sid,'history'=>$history,'customer'=>is_array($customer)?$customer:[]],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$ch=curl_init(N8N_WEBHOOK_URL);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$payload,CURLOPT_HTTPHEADER=>['Content-Type: application/json'],CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_TIMEOUT=>N8N_TIMEOUT_SECONDS,CURLOPT_SSL_VERIFYPEER=>true]);$body=curl_exec($ch);$err=curl_error($ch);$status=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($err||$status<200||$status>=300){error_log("[api/webhook] HTTP $status $err: $body");json_error('The AI service returned an error. Please try again.',502);}$r=json_decode((string)$body,true);$draft=is_array($r)?($r['draft']??$r['output']??null):null;if(!is_string($draft))json_error('The AI service did not return a draft.',502);json_response(['success'=>true,'draft'=>$draft]);}catch(Throwable $e){error_log('[api/webhook] '.$e->getMessage());json_error('Something went wrong while generating the draft.',500);}

